// App.jsx
import { ReactKeycloakProvider, useKeycloak } from "@react-keycloak/web";
import keycloak from './keycloak';

/* Bootstrap */
import 'bootstrap-icons/font/bootstrap-icons.css';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap/dist/js/bootstrap.min.js';

/* CSS */
import './App.css';

/* Components */
import Header from './components/Header';
import SideBar from './components/SideBar';
import Main from './components/Main';
import SignIn from './components/SignIn';

/* React */
import { useState, useEffect } from 'react';
import { Routes, Route, Navigate, useNavigate } from "react-router-dom";
import { Modal, Button } from 'react-bootstrap';

/* Data */
import { 
  getEmployees, getEmployeeByEmail, updateEmployee,
  updateAddress, deleteEmployee, getEmployeeByEmployeenr, getEmployeeForSettings,
  getEmployeeRoles, getNotificationsForEmployee, updateAuthenticatedEmployee,
  updateNotification, addAddress, addEmployee, getCategories, getCategoryById,
  addCategory, updateCategory, deleteCategory, getProducts, getProductByNr,
  addProduct, updateProduct, deleteProduct, getSuppliers, getSuppliersByProductnr,
  addProductToSupplier, getCustomerOrderByOrdernr, getCustomerOrders,
  addCustomerOrder, deleteCustomerOrder, getWarehouses, updateCustomerOrder,
  getCustomers, addCustomer, getCustomerByEmail, getPaymentMethods,
  getCustomerPaymentByOrdernr, getCustomerPayments, updateCustomerPayment,
  getOrderStatuses, getCustomerOrderProducts, createCustomerOrder,
  getLocationProducts, getLocationProductsByProductnr, getLocationProductsByWarehouse,
  getPriceHistoryByProductnr, getSellingHistoryByProduct
} from './data/ServerData';

// --- AppContent är barnet som använder useKeycloak ---
function AppContent() {
  const { keycloak } = useKeycloak(); // ✅ Fungerar nu
  const navigate = useNavigate();
  const [authorisedUser, setAuthorisedUser] = useState({});
  const [showErrorModal, setShowErrorModal] = useState(false);

  // Load user from localStorage
  useEffect(() => {
    const storedUser = localStorage.getItem('authorisedUser');
    if (storedUser) {
      setAuthorisedUser(JSON.parse(storedUser));
    }
  }, []);

  // Login function
  const login = (email, password) => {
    getEmployeeByEmail(email).then(employee => {
      if (employee && email === employee.email) {
        setAuthorisedUser(employee);
        localStorage.setItem('authorisedUser', JSON.stringify(employee));
        navigate("/inventory");
      } else {
        setShowErrorModal(true);
      }
    });
  };

  // Logout function
  const logout = () => {
    localStorage.removeItem('authorisedUser');
    setAuthorisedUser({});
    keycloak.logout({ redirectUri: window.location.origin });
  };

  const handleCloseErrorModal = () => setShowErrorModal(false);

  return (
    <>
      <Header
        authorisedUser={authorisedUser}
        logout={logout}
        getNotificationsForEmployee={getNotificationsForEmployee}
        updateNotification={updateNotification}
      />

      <Routes>
        {/* Public route */}
        <Route path="/signin" element={<SignIn login={login} />} />

        {/* Private routes */}
        {authorisedUser.email ? (
          <>
            <Route
              path="/inventory"
              element={
                <>
                  <SideBar authorisedUser={authorisedUser} />
                  <Main
                    authorisedUser={authorisedUser}
                    getSuppliers={getSuppliers}
                    getSuppliersByProductnr={getSuppliersByProductnr}
                    getCategories={getCategories}
                    getCategoryById={getCategoryById}
                    addCategory={addCategory}
                    updateCategory={updateCategory}
                    deleteCategory={deleteCategory}
                    getProducts={getProducts}
                    getProductByNr={getProductByNr}
                    addProduct={addProduct}
                    updateProduct={updateProduct}
                    deleteProduct={deleteProduct}
                    getWarehouses={getWarehouses}
                    getEmployees={getEmployees}
                    updateEmployee={updateEmployee}
                    updateAddress={updateAddress}
                    deleteEmployee={deleteEmployee}
                    getEmployeeByEmployeenr={getEmployeeByEmployeenr}
                    getEmployeeForSettings={getEmployeeForSettings}
                    getEmployeeByEmail={getEmployeeByEmail}
                    addAddress={addAddress}
                    addEmployee={addEmployee}
                    updateAuthenticatedEmployee={updateAuthenticatedEmployee}
                    getEmployeeRoles={getEmployeeRoles}
                    getNotificationsForEmployee={getNotificationsForEmployee}
                    updateNotification={updateNotification}
                    getCustomerOrderByOrdernr={getCustomerOrderByOrdernr}
                    getCustomerOrders={getCustomerOrders}
                    addCustomerOrder={addCustomerOrder}
                    deleteCustomerOrder={deleteCustomerOrder}
                    updateCustomerOrder={updateCustomerOrder}
                    getPaymentMethods={getPaymentMethods}
                    getCustomerPaymentByOrdernr={getCustomerPaymentByOrdernr}
                    getCustomerPayments={getCustomerPayments}
                    updateCustomerPayment={updateCustomerPayment}
                    getOrderStatuses={getOrderStatuses}
                    getCustomerOrderProducts={getCustomerOrderProducts}
                    getLocationProductsByWarehouse={getLocationProductsByWarehouse}
                    getLocationProducts={getLocationProducts}
                    getLocationProductsByProductnr={getLocationProductsByProductnr}
                    getCustomers={getCustomers}
                    addCustomer={addCustomer}
                    getCustomerByEmail={getCustomerByEmail}
                    getPriceHistoryByProductnr={getPriceHistoryByProductnr}
                    getSellingHistoryByProduct={getSellingHistoryByProduct}
                  />
                </>
              }
            />
            <Route path="*" element={<Navigate to="/inventory" replace />} />
          </>
        ) : (
          <Route path="*" element={<Navigate to="/signin" replace />} />
        )}
      </Routes>

      {/* Error Modal */}
      <Modal show={showErrorModal} onHide={handleCloseErrorModal} className="modal-centered">
        <Modal.Header closeButton>
          <Modal.Title>Authentication Error</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          Wrong email or password! If you forget your password, contact us: inventhor@support.no
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleCloseErrorModal}>
            Close
          </Button>
        </Modal.Footer>
      </Modal>
    </>
  );
}

// --- App omsluter AppContent med ReactKeycloakProvider ---
function App() {
  return (
    <ReactKeycloakProvider authClient={keycloak} initOptions={{ checkLoginIframe: false }}>
      <AppContent />
    </ReactKeycloakProvider>
  );
}

export default App;
